def source(n,title,authors,url,identifier,date,version,epoch,measurement,access,loc,family,query,datebasis='First arXiv submission of this measurement report, verified in submission history'):
 sources.append(dict(source_id=f'Y2026S{n:02d}',year=2026,title=title,authors_or_collaboration=authors,primary_url=url,identifier=identifier,report_date=date,date_precision='day' if len(date)==10 else 'month',date_basis=datebasis,version=version,observation_epoch=epoch,measurement=measurement,data_access=access,verification='Opened the primary report/release page and read its measurement description and date/version metadata. This authenticates the report, not its conclusions. Full likelihood files, numerical tables and covariance contents were not audited; acquire and hash before inference.',source_locator=loc,overlap_family=family,search_queries=[query],checked_on='2026-09-27'))
